const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('vi-VN').format(n)+' ₫',num=n=>new Intl.NumberFormat('vi-VN').format(n);
let state;try{state=JSON.parse(localStorage.getItem('storix-v1'))||Core.seed()}catch{state=Core.seed()}
const validRoles=['Quản lý','Nhân viên','Chỉ xem'];
let role=null,page='dashboard',query='';
try{const savedRole=sessionStorage.getItem('storix-role');if(validRoles.includes(savedRole))role=savedRole}catch{}
function enterWorkspace(){const selectedRole=$('#role').value;if(!validRoles.includes(selectedRole))return;role=selectedRole;page='dashboard';query='';try{sessionStorage.setItem('storix-role',role)}catch{}render()}
function logout(){role=null;page='dashboard';query='';try{sessionStorage.removeItem('storix-role')}catch{}login()}
const nav=[['dashboard','▦','Tổng quan'],['products','▧','Sản phẩm'],['locations','▥','Kho & bãi lưu trữ'],['stock','▤','Tồn kho'],['docs','⇄','Nhập · xuất · điều chuyển'],['sales','▱','Bán hàng'],['count','✓','Kiểm kê'],['partners','♧','Đối tác'],['alerts','♧','Cảnh báo'],['reports','▥','Báo cáo'],['logs','◷','Nhật ký']];
function save(action){state.logs.unshift({time:new Date().toLocaleString('vi-VN'),user:role,action});try{localStorage.setItem('storix-v1',JSON.stringify(state))}catch{toast('Không lưu được dữ liệu: bộ nhớ trình duyệt đã đầy.')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function pname(id){return state.products.find(x=>x.id===id)?.name||id}function lname(id){return state.locations.find(x=>x.id===id)?.name||id}function total(p){return state.stock.filter(x=>x.product===p).reduce((a,x)=>a+x.qty,0)}
function canEdit(){return role!=='Chỉ xem'}function canApprove(){return role==='Quản lý'}function button(label,action,primary=false){return `<button ${primary?'class="primary"':''} onclick="${action}">${label}</button>`}
function table(head,rows){return `<div class="tablewrap"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${head.length}" class="empty">Chưa có dữ liệu phù hợp</td></tr>`}</tbody></table></div>`}
function tag(t){return `<span class="pill ${t==='Hoàn thành'?'good':t==='Chờ duyệt'?'warn':t==='Đã hủy'?'bad':''}">${esc(t)}</span>`}
function matches(x){return JSON.stringify(x).toLocaleLowerCase('vi').includes(query.toLocaleLowerCase('vi'))}
function go(p){page=p;query='';render()}
function login(){ $('#app').innerHTML=`<div class="login"><section class="intro"><div class="brand">storix<span>◆</span></div><span class="tag">WORKSPACE DEMO</span><h1>Mọi hàng hóa.<br>Một góc nhìn.</h1><p>Kết nối sản phẩm, kho hàng và bãi lưu trữ.<br>Trải nghiệm quy trình vận hành của nhóm bạn.</p><p style="margin-top:70px;font-size:13px">Dựa trên backlog Jira · Project CN</p></section><section class="loginform"><div class="panel"><h1>Chào mừng đến Storix</h1><p>Chọn vai trò để trải nghiệm bản demo.</p><label class="field">Vai trò<select id="role"><option>Quản lý</option><option>Nhân viên</option><option>Chỉ xem</option></select></label><button class="primary" style="width:100%" onclick="enterWorkspace()">Vào không gian làm việc →</button><p class="foot">Đăng nhập và quyền hạn được mô phỏng. Dữ liệu lưu riêng trên trình duyệt; chưa kết nối database.</p></div></section></div>`;}
function render(){if(!role)return login();$('#app').innerHTML=`<aside><div class="brand">storix<span>◆</span></div><small>KHÔNG GIAN LÀM VIỆC</small><nav>${nav.map(([id,ico,label])=>`<button class="${page===id?'active':''}" onclick="go('${id}')">${ico} &nbsp; ${label}</button>`).join('')}</nav><div class="badge">● &nbsp; Chế độ demo<br>Dữ liệu trên trình duyệt này</div></aside><main><header><span class="workspace">Vận hành / <span class="muted">${nav.find(x=>x[0]===page)[2]}</span></span><div class="split"><span class="tag">${esc(role)}</span>${button('Đăng xuất',"logout()")}</div></header><div class="content"><div class="heading"><div><h1>${nav.find(x=>x[0]===page)[2]}</h1><p>${page==='dashboard'?'Nắm bắt hoạt động kho hàng của bạn trong hôm nay.':'Quản lý tập trung · Dữ liệu mẫu có thể thao tác'}</p></div><div class="split">${canEdit()&&['dashboard','docs','sales','count'].includes(page)?button('+ Tạo '+(page==='sales'?'đơn bán':page==='count'?'kiểm kê':'chứng từ'),`docForm('${page==='sales'?'Bán hàng':page==='count'?'Kiểm kê':'Nhập hàng'}')`,true):''}${page==='products'&&canEdit()?button('+ Thêm sản phẩm','productForm()',true):''}${page==='locations'&&canEdit()?button('+ Thêm nơi lưu trữ','locationForm()',true):''}${page==='partners'&&canEdit()?button('+ Thêm đối tác','partnerForm()',true):''}</div></div><div id="body"></div><div class="foot">STORIX DEMO · Chưa kết nối database · Số liệu mẫu, không đồng bộ giữa các thiết bị</div></div></main>`;renderBody()}
function searchbar(){return `<div class="toolbar"><input aria-label="Tìm kiếm" placeholder="Tìm kiếm mã, tên, trạng thái…" value="${esc(query)}" oninput="query=this.value;renderRows()"><button onclick="exportCSV()">↓ Xuất CSV</button></div>`}
function renderBody(){let b=$('#body');if(page==='dashboard')return dashboard();if(page==='alerts'){b.innerHTML=`<div class="panel"><h2>Cần chú ý</h2>${state.products.filter(p=>total(p.id)<p.min).map(p=>`<div class="notice"><b>${esc(p.name)}</b><span class="pill warn">Tồn thấp: ${total(p.id)} / tối thiểu ${p.min}</span> ${button('Xem sản phẩm',"go('products')")}</div>`).join('')||'<p>Không có sản phẩm dưới mức tồn tối thiểu.</p>'}${state.locations.filter(l=>used(l.id)/l.capacity>=.8).map(l=>`<div class="notice"><b>${esc(l.name)} gần đầy</b>Đã dùng ${used(l.id)} / ${l.capacity}</div>`).join('')}</div>`;return}
if(page==='reports'){b.innerHTML=`<div class="panel"><h2>Báo cáo tồn kho hiện tại</h2><p>Tổng giá trị theo giá bán tham khảo: <b>${money(state.products.reduce((a,p)=>a+total(p.id)*p.price,0))}</b></p><div class="toolbar">${button('↓ Xuất CSV','exportCSV()')}${button('In / Lưu PDF','window.print()')}</div>${stockTable()}</div><div class="panel" style="margin-top:20px"><h2>Hoạt động đã hoàn thành</h2>${['Nhập hàng','Xuất hàng','Điều chuyển','Bán hàng','Kiểm kê'].map(t=>`<p>${t}: <b>${state.docs.filter(d=>d.type===t&&d.status==='Hoàn thành').length}</b> chứng từ</p>`).join('')}<p>Doanh thu đơn hoàn thành: ${money(state.docs.filter(d=>d.type==='Bán hàng'&&d.status==='Hoàn thành').reduce((a,d)=>a+d.amount,0))}</p></div>`;return}
b.innerHTML=`<div class="panel">${searchbar()}<div id="rows"></div></div>`;renderRows()}
function used(id){return state.stock.filter(x=>x.location===id).reduce((a,x)=>a+x.qty,0)}
function dashboard(){let low=state.products.filter(p=>total(p.id)<p.min).length;$('#body').innerHTML=`<div class="cards">${[['Sản phẩm',state.products.length,'products','▧'],['Tổng lượng tồn',state.stock.reduce((a,x)=>a+x.qty,0),'stock','▤'],['Phiếu chờ duyệt',state.docs.filter(d=>d.status==='Chờ duyệt').length,'docs','⇄'],['Cảnh báo tồn thấp',low,'alerts','!']].map(([t,n,p,i])=>`<div class="card" role="button" tabindex="0" onclick="go('${p}')" onkeydown="if(event.key==='Enter')go('${p}')"><span class="icon">${i}</span><span class="muted">${t}</span><strong>${num(n)}</strong><small class="muted">Xem chi tiết ↗</small></div>`).join('')}</div><div class="grid"><div class="panel"><h2>Phân bố tồn kho theo sản phẩm</h2><p>Số lượng hiện có và ngưỡng tồn tối thiểu</p><div class="chart">${state.products.slice(0,6).map(p=>{let max=Math.max(...state.products.map(p=>Math.max(total(p.id),p.min)),1);return `<div title="${esc(p.name)}: ${total(p.id)}"><i style="height:${total(p.id)/max*100}%"></i><i style="height:${p.min/max*100}%"></i><small>${p.id}</small></div>`}).join('')}</div><div class="legend"><span>● Tồn hiện tại</span><span style="color:#83b7a9">● Tồn tối thiểu</span></div></div><div class="panel"><h2>Sức chứa kho & bãi</h2>${state.locations.map(l=>`<div class="location"><label><b>${esc(l.name)}</b><span>${Math.round(used(l.id)/l.capacity*100)}%</span></label><div class="bar"><i style="width:${Math.min(100,used(l.id)/l.capacity*100)}%"></i></div><small class="muted">${num(used(l.id))} / ${num(l.capacity)} đơn vị quy ước</small></div>`).join('')}</div></div><div class="panel"><div class="heading"><h2>Chứng từ gần đây</h2>${button('Tất cả chứng từ →',"go('docs')")}</div>${docsTable(state.docs.slice(0,5))}</div>`}
function stockTable(){return table(['Sản phẩm','Nơi lưu trữ','Tồn thực tế','Đơn vị'],state.stock.filter(x=>matches({...x,name:pname(x.product),place:lname(x.location)})).map(x=>`<tr><td><b>${esc(pname(x.product))}</b><small>${esc(x.product)}</small></td><td>${esc(lname(x.location))}</td><td><b>${num(x.qty)}</b></td><td>${esc(state.products.find(p=>p.id===x.product)?.unit)}</td></tr>`))}
function docsTable(ds){return table(['Chứng từ','Loại','Sản phẩm','Số lượng','Nơi lưu trữ','Trạng thái','Thao tác'],ds.filter(matches).map(d=>`<tr><td><b>${esc(d.id)}</b><small>${esc(d.date)}</small></td><td>${esc(d.type)}</td><td>${esc(pname(d.product))}${d.type==='Bán hàng'?`<br><small>${money(d.amount)} · ${esc(d.payment)}</small>`:''}</td><td>${num(d.qty)}</td><td>${esc(lname(d.from))}${d.type==='Điều chuyển'?'<br>→ '+esc(lname(d.to)):''}</td><td>${tag(d.status)}</td><td>${canApprove()&&d.status==='Chờ duyệt'?button('Duyệt',`transition('${d.id}','Đã duyệt')`):''}${canEdit()&&d.status==='Đã duyệt'?button('Hoàn thành',`transition('${d.id}','Hoàn thành')`):''}${canEdit()&&['Chờ duyệt','Đã duyệt'].includes(d.status)?button('Hủy',`transition('${d.id}','Đã hủy')`):''}</td></tr>`))}
function renderRows(){let html='';if(page==='products')html=table(['Mã / sản phẩm','Danh mục','Giá bán','Tồn / tối thiểu','Trạng thái',''],state.products.filter(matches).map(p=>`<tr><td><b>${esc(p.name)}</b><small>${esc(p.id)} · ${esc(p.unit)}</small></td><td>${esc(p.category)}</td><td>${money(p.price)}</td><td>${total(p.id)} / ${p.min}</td><td>${tag(p.active?'Đang kinh doanh':'Ngừng kinh doanh')}</td><td>${canEdit()?button('Chỉnh sửa',`productForm('${p.id}')`):''}</td></tr>`));if(page==='stock')html=stockTable();if(page==='locations')html=table(['Mã','Tên nơi lưu trữ','Loại','Sức chứa','Đã sử dụng'],state.locations.filter(matches).map(l=>`<tr><td>${esc(l.id)}</td><td><b>${esc(l.name)}</b></td><td>${esc(l.type)}</td><td>${num(l.capacity)}</td><td>${num(used(l.id))} (${Math.round(used(l.id)/l.capacity*100)}%)</td></tr>`));if(['docs','sales','count'].includes(page))html=docsTable(state.docs.filter(d=>page==='sales'?d.type==='Bán hàng':page==='count'?d.type==='Kiểm kê':true));if(page==='partners')html=table(['Mã','Tên đối tác','Loại','Điện thoại'],state.partners.filter(matches).map(p=>`<tr><td>${esc(p.id)}</td><td><b>${esc(p.name)}</b></td><td>${esc(p.type)}</td><td>${esc(p.phone)}</td></tr>`));if(page==='logs')html=table(['Thời gian','Vai trò','Thao tác'],state.logs.filter(matches).map(l=>`<tr><td>${esc(l.time)}</td><td>${esc(l.user)}</td><td>${esc(l.action)}</td></tr>`));$('#rows').innerHTML=html}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" value="${esc(value)}" type="${type}" required ${extra}></label>`}function select(label,name,items,value){return `<label class="field">${label}<select name="${name}">${items.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}
function modal(title,body,submit){$('#modal').innerHTML=`<h2>${title}</h2><form id="form">${body}<div class="error" id="error"></div><div class="actions"><button type="button" onclick="$('#modal').close()">Đóng</button><button class="primary">Lưu thông tin</button></div></form>`;$('#form').onsubmit=e=>{e.preventDefault();try{if(!canEdit())throw Error('Vai trò chỉ xem không được thay đổi dữ liệu.');submit(Object.fromEntries(new FormData(e.target)));$('#modal').close();render();toast('Đã lưu thành công')}catch(e){$('#error').textContent=e.message}};$('#modal').showModal()}
function productForm(id){const p=state.products.find(p=>p.id===id)||{id:'SP'+String(state.products.length+1).padStart(3,'0'),price:0,min:10,unit:'Cái',active:true};modal(id?'Cập nhật sản phẩm':'Thêm sản phẩm',`<div class="formgrid">${field('Mã sản phẩm','id',p.id,'text',id?'readonly':'pattern="[A-Za-z0-9_-]+"')}${field('Tên sản phẩm','name',p.name)}${field('Danh mục','category',p.category)}${field('Đơn vị','unit',p.unit)}${field('Giá bán (đ)','price',p.price,'number','min="0" max="1000000000"')}${field('Tồn tối thiểu','min',p.min,'number','min="0" max="1000000"')}${select('Trạng thái','active',[['true','Đang kinh doanh'],['false','Ngừng kinh doanh']],String(p.active))}</div>`,f=>{if(!id&&state.products.some(p=>p.id===f.id))throw Error('Mã sản phẩm đã tồn tại.');if(!f.name.trim()||!f.category.trim())throw Error('Vui lòng nhập đầy đủ tên và danh mục.');Object.assign(p,f,{price:+f.price,min:+f.min,active:f.active==='true'});if(!id)state.products.push(p);save('Lưu sản phẩm '+p.id)})}
function locationForm(){modal('Thêm nơi lưu trữ',field('Tên nơi lưu trữ','name')+select('Loại','type',[['Kho','Kho'],['Bãi','Bãi'],['Cửa hàng','Cửa hàng']])+field('Sức chứa (đơn vị quy ước)','capacity',500,'number','min="1" max="10000000"'),f=>{state.locations.push({...f,id:'VT'+Date.now(),capacity:+f.capacity});save('Thêm nơi lưu trữ '+f.name)})}
function partnerForm(){modal('Thêm đối tác',field('Tên đối tác','name')+select('Loại','type',[['Nhà cung cấp','Nhà cung cấp'],['Khách hàng','Khách hàng']])+field('Điện thoại','phone','','tel','pattern="[0-9+ ()-]{8,20}"'),f=>{state.partners.push({...f,id:'DT'+Date.now()});save('Thêm đối tác '+f.name)})}
function docForm(type){const loc=state.locations.map(l=>[l.id,l.name]);modal('Tạo chứng từ',`<div class="formgrid">${select('Loại chứng từ','type',['Nhập hàng','Xuất hàng','Điều chuyển','Kiểm kê','Bán hàng','Trả NCC'].map(t=>[t,t]),type)}${select('Sản phẩm','product',state.products.filter(p=>p.active).map(p=>[p.id,p.name]))}${select('Nơi nhập / nơi xuất / kiểm kê','from',loc)}${select('Nơi đến (chỉ điều chuyển)','to',loc,loc[1]?.[0])}${field('Số lượng (kiểm kê: số thực tế)','qty',1,'number','min="0" max="1000000"')}${select('Đối tác (nếu có)','partner',[['','Không chọn'],...state.partners.map(p=>[p.id,p.name])])}${select('Thanh toán (đơn bán)','payment',[['Tiền mặt','Tiền mặt'],['Chuyển khoản demo','Chuyển khoản demo']])}${field('Giảm giá % (đơn bán)','discount',0,'number','min="0" max="100"')}</div><p class="foot">Phiếu chờ duyệt chưa thay đổi tồn kho. Quản lý duyệt, sau đó hoàn thành để ghi nhận. Sức chứa sử dụng đơn vị quy ước cho demo.</p>`,f=>{let p=state.products.find(p=>p.id===f.product);if(!p)throw Error('Cần tạo sản phẩm trước.');if(f.type!=='Kiểm kê'&&+f.qty<=0)throw Error('Số lượng phải lớn hơn 0.');if(f.type==='Điều chuyển'&&f.from===f.to)throw Error('Nơi đi và nơi đến phải khác nhau.');let d={...f,qty:+f.qty,id:'CT'+Date.now(),date:Core.today(),status:'Chờ duyệt',amount:Math.round(p.price*Number(f.qty)*(1-Number(f.discount)/100))};state.docs.unshift(d);save('Tạo '+d.type+' '+d.id)})}
function transition(id,status){if(!canEdit())return;let d=state.docs.find(d=>d.id===id);if(!d)return;try{if(status==='Đã duyệt'){if(!canApprove()||d.status!=='Chờ duyệt')throw Error('Chỉ quản lý được duyệt phiếu chờ duyệt.');d.status=status}else if(status==='Hoàn thành'){Core.apply(state,d)}else{if(!['Chờ duyệt','Đã duyệt'].includes(d.status))throw Error('Không thể hủy phiếu đã hoàn thành.');if(!confirm('Hủy chứng từ này?'))return;d.status=status}save(status+' '+id);render();toast('Đã cập nhật chứng từ')}catch(e){toast(e.message)}}
function exportCSV(){let rows;if(['stock','reports','dashboard'].includes(page))rows=[['Sản phẩm','Kho','Số lượng'],...state.stock.map(x=>[pname(x.product),lname(x.location),x.qty])];else if(page==='products')rows=[['Mã','Tên','Danh mục','Giá','Tồn'],...state.products.filter(matches).map(p=>[p.id,p.name,p.category,p.price,total(p.id)])];else if(page==='locations')rows=[['Mã','Tên','Loại','Sức chứa','Đã dùng'],...state.locations.filter(matches).map(l=>[l.id,l.name,l.type,l.capacity,used(l.id)])];else if(page==='partners')rows=[['Mã','Tên','Loại','Điện thoại'],...state.partners.filter(matches).map(p=>[p.id,p.name,p.type,p.phone])];else if(page==='logs')rows=[['Thời gian','Vai trò','Thao tác'],...state.logs.filter(matches).map(l=>[l.time,l.user,l.action])];else rows=[['Mã','Loại','Sản phẩm','Số lượng','Trạng thái'],...state.docs.filter(d=>(page==='sales'?d.type==='Bán hàng':page==='count'?d.type==='Kiểm kê':true)&&matches(d)).map(d=>[d.id,d.type,pname(d.product),d.qty,d.status])];let safe=v=>{let s=String(v);if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};let blob=new Blob(['\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='storix-'+page+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
render();
